from dfdlib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
b = Board('DFD_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('What it shows', ul('How data moves: where it comes from, what changes it, where it rests and where it goes. Not the order of steps (Flowchart, BPMN) and not the order in time (Sequence).', 'Good for explaining a system to someone who does not write code, and for finding data that is stored but never used, or used but never stored.')),
 card('Four symbols', ul('<b>External entity:</b> square corners, E1, E2. Outside the system.', '<b>Process:</b> rounded, number in a header strip. Verb phrase name.', '<b>Data store:</b> open on the right, D1, D2. Noun name.', '<b>Data flow:</b> arrow with a noun label. Never a verb.', 'Gane-Sarson style. The shapes are the only thing that differs from other DFD styles.')),
 card('Levels', ul('<b>Level 0, context:</b> one process, only the outside parties. Shows the border.', '<b>Level 1:</b> that process opened into 4 to 7. Stores appear here.', '<b>Level 2:</b> one level-1 process opened into 3 to 6. Number its children 4.1, 4.2...', 'Opening a process keeps every flow that crossed it, from the same neighbours (balancing). A flow may be split into its parts, but never appear or vanish between levels.', 'Do not go past level 2 on one page.')),
 card('Connections', ul('Allowed: entity ↔ process, process ↔ process (only on level 2), process ↔ store.', 'Never: entity to entity, store to store, entity to store. The Notation page shows each.', 'A process needs at least one flow in and one flow out.', 'A store needs at least one flow in and one out somewhere in the diagram set.', 'Two parties that exchange data both ways get two arrows, side by side, 90 px apart.')),
 card('Lines and labels', ul('Straight or orthogonal, at most two bends. Arrow at the receiver.', 'Roles as in other diagrams: main route blue, thick, animated; a flow that only reports status violet, thin, slow; the rest ink.', 'Label every flow with a noun phrase (<i>Order ticket</i>, <i>Payment result</i>). Leave 90 px for it.', 'Parallel pair: 60 px apart, labels centred on their own line.')),
 card('Layout', ul('Outside parties on the outside edge, processes in the middle, stores between the processes that share them.', 'Process 260 × 124, entity 240 × 80, store 260 × 64 (an open store is wider when many lines meet it).', 'Columns 640 px apart, rows 400 px apart. At least 240 px of line between boxes with a label.', 'Name, tint and icon of an entity or process are the same as in every other diagram.')),
 card('Animation', ul('One blue route: the main journey of the data (basket, amount, charge). Violet for status flows. Everything else static.', 'In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('What a plugin can rely on', ul('A node is: id (E1, 1.0, D1), kind (entity, process, store), name, description, icon, tone. A flow is: from, to, label, kind.', 'Checks: no forbidden connection, every process has input and output, ids unique and numbered by level, flows balance across levels.', 'The level-2 diagram takes its neighbours from level 1.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">DFD · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">A data flow diagram follows data through a system. These are the conventions every DFD follows, and that a plugin can rely on. Notation shows the four symbols and the three forbidden connections; the examples show the delivery system at levels 0, 1 and 2.</div></div>{grid}</div>')
print(save10(b))
